draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var I = p.current, B = p.field, L = p.sep, m = p.mass / 1000;
var F = I * L * B;
var a = F / m;

function arrow(x1, y1, x2, y2, col) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 1.8;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var an = Math.atan2(y2 - y1, x2 - x1), h = 8;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - h * Math.cos(an - 0.42), y2 - h * Math.sin(an - 0.42));
  ctx.lineTo(x2 - h * Math.cos(an + 0.42), y2 - h * Math.sin(an + 0.42));
  ctx.closePath(); ctx.fill();
}

var yTop = H * 0.28, yBot = H * 0.78;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(W * 0.08, yTop); ctx.lineTo(W * 0.94, yTop);
ctx.moveTo(W * 0.08, yBot); ctx.lineTo(W * 0.94, yBot);
ctx.moveTo(W * 0.08, yTop); ctx.lineTo(W * 0.08, yBot);
ctx.stroke();

ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
var i, j;
for (i = 0; i < 8; i++) {
  for (j = 0; j < 2; j++) {
    var dx = W * 0.18 + i * W * 0.095, dy = yTop + (j + 1) * (yBot - yTop) / 3;
    ctx.beginPath();
    ctx.moveTo(dx - 3.5, dy - 3.5); ctx.lineTo(dx + 3.5, dy + 3.5);
    ctx.moveTo(dx + 3.5, dy - 3.5); ctx.lineTo(dx - 3.5, dy + 3.5);
    ctx.stroke();
  }
}

var span = W * 0.70;
var tt = t % 2.2;
var s = 0.5 * a * tt * tt * 0.004;
if (s > 1) { s = 1; }
var xr = W * 0.16 + s * span * 0.9;

ctx.strokeStyle = C.accent;
ctx.lineWidth = 5;
ctx.beginPath(); ctx.moveTo(xr, yTop); ctx.lineTo(xr, yBot); ctx.stroke();

arrow(xr, yBot - 6, xr, yTop + 10, C.figure);
ctx.fillStyle = C.ink;
ctx.fillText("I", xr - 12, (yTop + yBot) / 2);

arrow(xr, H * 0.15, xr + Math.min(W * 0.22, 30 + F * 60), H * 0.15, C.accent);
ctx.fillStyle = C.ink;
ctx.fillText("F = I L B", xr + 10, H * 0.12);
ctx.fillText("B into the page", W * 0.08, 14);
ctx.fillText("rails", W * 0.08, yBot + 16);

out.note = "F = " + F.toFixed(3) + " N,  a = " + a.toFixed(1) + " m/s^2  (reverse nothing: flip I or B and the rod runs the other way)";
